import{_ as s,a0 as l,w as p,s as d,ao as n,I as i,x as a,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"克隆 MAC 地址來繞過強制門户 | LCTT x X-CMD","titleTemplate":false,"description":"克隆 MAC 地址來繞過強制門户 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"克隆 MAC 地址來繞過強制門户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"克隆 MAC 地址來繞過強制門户 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191104 Cloning a MAC address to bypass a captive portal","title":"克隆 MAC 地址來繞過強制門户","tag":"201911","desc":""},"relativePath":"201911/20191104 Cloning a MAC address to bypass a captive portal.md","filePath":"[post].md"}'),C={name:"201911/20191104 Cloning a MAC address to bypass a captive portal.md"};function m(u,t,A,M,g,f){const e=l("Link");return p(),d("div",null,[t[21]||(t[21]=n('<h1 id="克隆-mac-地址來繞過強制門户" tabindex="-1">克隆 MAC 地址來繞過強制門户 <a class="header-anchor" href="#克隆-mac-地址來繞過強制門户" aria-label="Permalink to “克隆 MAC 地址來繞過強制門户”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/10/clone-mac-nm-816x345.jpg" alt=""></p><p>如果你曾經在家和辦公室之外連接到 WiFi，那麼通常會看到一個門户頁面。它可能會要求你接受服務條款或其他協議才能訪問。但是，當你無法通過這類門户進行連接時會發生什麼？本文向你展示瞭如何在 Fedora 上使用 NetworkManager 在某些故障情況下讓你仍然可以訪問互聯網。</p><h3 id="強制門户如何工作" tabindex="-1">強制門户如何工作 <a class="header-anchor" href="#強制門户如何工作" aria-label="Permalink to “強制門户如何工作”">​</a></h3><p>強制門户是新設備連接到網絡時顯示的網頁。當用户首次訪問互聯網時，門户網站會捕獲所有網頁請求並將其重定向到單個門户頁面。</p>',5)),i("p",null,[t[1]||(t[1]=a("然後，頁面要求用户採取一些措施，通常是同意使用政策。用户同意後，他們可以向 RADIUS 或其他類型的身份驗證系統進行身份驗證。簡而言之，強制門户根據設備的 MAC 地址和終端用户接受條款來註冊和授權設備。（MAC 地址是附加到任何網絡接口的",-1)),r(e,{href:"https://en.wikipedia.org/wiki/MAC_address"},{default:o(()=>[...t[0]||(t[0]=[a("基於硬件的值",-1)])]),_:1}),t[2]||(t[2]=a("，例如 WiFi 芯片或卡。）",-1))]),t[22]||(t[22]=n('<p>有時設備無法加載強制門户來進行身份驗證和授權以使用 WiFI 接入。這種情況的例子包括移動設備和遊戲機（Switch、Playstation 等）。當連接到互聯網時，它們通常不會打開強制門户頁面。連接到酒店或公共 WiFi 接入點時，你可能會看到這種情況。</p><p>不過，你可以在 Fedora 上使用 NetworkManager 來解決這些問題。Fedora 可以使你臨時克隆要連接的設備的 MAC 地址，並代表該設備通過強制門户進行身份驗證。你需要得到連接設備的 MAC 地址。通常，它被打印在設備上的某個地方並貼上標籤。它是一個六字節的十六進制值，因此看起來類似 <code>4A:1A:4C:B0:38:1F</code>。通常，你也可以通過設備的內置菜單找到它。</p><h3 id="使用-networkmanager-克隆" tabindex="-1">使用 NetworkManager 克隆 <a class="header-anchor" href="#使用-networkmanager-克隆" aria-label="Permalink to “使用 NetworkManager 克隆”">​</a></h3><p>首先，打開 <code>nm-connection-editor</code>，或通過“設置”打開 WiFi 設置。然後，你可以使用 NetworkManager 進行克隆：</p><ul><li>對於以太網：選擇已連接的以太網連接。然後選擇 “Ethernet” 選項卡。記錄或複製當前的 MAC 地址。在 “<ruby>克隆 MAC 地址<rt>Cloned MAC address</rt></ruby>” 字段中輸入遊戲機或其他設備的 MAC 地址。</li><li>對於 WiFi：選擇 WiFi 配置名。然後選擇 “WiFi” 選項卡。記錄或複製當前的 MAC 地址。在 “<ruby>克隆 MAC 地址<rt>Cloned MAC address</rt></ruby>” 字段中輸入遊戲機或其他設備的 MAC 地址。</li></ul><h3 id="啓動所需的設備" tabindex="-1">啓動所需的設備 <a class="header-anchor" href="#啓動所需的設備" aria-label="Permalink to “啓動所需的設備”">​</a></h3><p>當 Fedora 系統與以太網或 WiFi 配置連接，克隆的 MAC 地址將用於請求 IP 地址，並加載強制門户。輸入所需的憑據和/或選擇用户協議。該 MAC 地址將獲得授權。</p><p>現在，斷開 WiF i或以太網配置連接，然後將 Fedora 系統的 MAC 地址更改回其原始值。然後啓動遊戲機或其他設備。該設備現在應該可以訪問互聯網了，因為它的網絡接口已通過你的 Fedora 系統進行了授權。</p>',8)),i("p",null,[t[4]||(t[4]=a("不過，這不是 NetworkManager 全部能做的。例如，請參閲",-1)),r(e,{href:"https://linux.cn/article-10028-1.html"},{default:o(()=>[...t[3]||(t[3]=[a("隨機化系統硬件地址",-1)])]),_:1}),t[5]||(t[5]=a("，來獲得更好的隱私保護。",-1))]),t[23]||(t[23]=i("hr",null,null,-1)),i("p",null,[t[7]||(t[7]=a("via: ",-1)),r(e,{href:"https://fedoramagazine.org/cloning-a-mac-address-to-bypass-a-captive-portal/"},{default:o(()=>[...t[6]||(t[6]=[a("https://fedoramagazine.org/cloning-a-mac-address-to-bypass-a-captive-portal/",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=a("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/swilson/"},{default:o(()=>[...t[8]||(t[8]=[a("Esteban Wilson",-1)])]),_:1}),t[13]||(t[13]=a(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[9]||(t[9]=[a("lujun9972",-1)])]),_:1}),t[14]||(t[14]=a(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[10]||(t[10]=[a("geekpi",-1)])]),_:1}),t[15]||(t[15]=a(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=a("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[a("LCTT",-1)])]),_:1}),t[19]||(t[19]=a(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[a("Linux中國",-1)])]),_:1}),t[20]||(t[20]=a(" 榮譽推出",-1))])])}const x=s(C,[["render",m]]);export{k as __pageData,x as default};
